load=lambda n:json.loads((p/n).read_text())
parts=load('parts.json');cad=load('cad_report.json');r=load('mechanism_report.json');cost=load('cost_estimate.json')
def h(s):return html.escape(str(s))
def money(x):return f'${x:,.3f}' if 0<x<.1 else f'${x:,.2f}'
def table(headers,rows):return '<div class="table-scroll"><table><thead><tr>'+''.join('<th>'+h(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
# Feedstock only. These rates/yields are deliberately visible allowances, not commodity quotes.
rates={'PEEK':(50,150,.25),'Titanium':(50,300,.15),'Steel':(2,15,.20),'NdFeB':(60,250,.30),'FR4':(100,500,.50),'Copper':(10,25,.50),'Polyimide':(100,400,.50)}
