# Spending caps, NOT vendor prices or verified replacement components.
budgets=[('Two custom motor + reduction units',2,4.50,'New design + supplier quote + torque/speed/endurance proof required'),('One custom bare motor',1,2.00,'Must fit and meet direct-slide torque; unselected'),('MCU',1,2.00,'Cost ceiling; exact buying price unverified'),('Three motor driver ICs',3,1.10,'Cost ceiling; exact buying price unverified'),('Wireless receiver IC',1,2.00,'Existing receiver architecture; raised-swarm delivery unresolved'),('Charger / control converter / motor converter / OR / buffers',1,3.60,'Combined IC budget; not a verified quote'),('Inductors and all passives',1,2.00,'Netlist and passive values incomplete'),('Bare four-layer PCB',1,1.20,'Routed board + panel yield quote required'),('PCB component assembly',1,1.50,'Stencil/panel/test assumptions'),('1 F reserve capacitor',1,.80,'Supplier volume quote and ESR confirmation required'),('Wireless coil',1,1.20,'Existing coil max stack must be retained or revalidated'),('Flex / wiring',1,1.00,'Routing unimplemented'),('Molded sphere and triangular ramp pods',1,1.30,'Tooling excluded; micro-molding quote required'),('48 custom split magnets',48,.045,'Custom geometry; cutting/coating/yield quote required'),('48 pole pieces',48,.020,'Micro-stamping/MIM quote and magnetic circuit validation required'),('24 radial supports',24,.020,'Microfabrication quote required'),('Four custom reduction gears',4,.10,'Tooling, tooth life and efficiency unverified'),('Tendon, latch, clutch, brake and sensor allowance',1,4.00,'Incomplete mechanism; largest cost and packaging risk'),('Final assembly and test',1,4.00,'Automation/yield unverified')]
